// ProtoContext configuration shared by the protocol harnesses (fuzz_proto, fuzz_psid_cookie):
// the same settings upstream's test/unittests/test_proto.cpp uses, with upstream's test PKI
// (test/ssl/, embedded by mayhem/gen_test_keys.sh).
// mode: 0 = no control-channel wrapping, 1 = tls-auth, 2 = tls-crypt, 3 = tls-crypt-v2.
#pragma once
#include "fuzz_rand.hpp"
#include "ovpn_test_keys.hpp" // generated by mayhem/build.sh from test/ssl/

#include <openvpn/ssl/sslchoose.hpp>
#include <openvpn/ssl/proto.hpp>
#include <openvpn/frame/frame_init.hpp>
#include <openvpn/crypto/cryptodcsel.hpp>
#include <openvpn/crypto/tls_crypt_v2.hpp>
#include <openvpn/init/initprocess.hpp>

namespace fuzz {
using namespace openvpn;

class FuzzStats : public SessionStats
{
};

// The SSL factory (OpenSSL SSL_CTX with the test PKI loaded) is built once per role and reused:
// loading certificates and DH parameters dominates the cost of an input otherwise. It is
// configuration only; every input's ProtoContext creates its own SSL session from it.
SSLFactoryAPI::Ptr ssl_factory(bool server, Frame::Ptr frame)
{
    static SSLFactoryAPI::Ptr cache[2];
    SSLFactoryAPI::Ptr &f = cache[server ? 1 : 0];
    if (f)
        return f;
    SSLLib::SSLAPI::Config::Ptr sc(new SSLLib::SSLAPI::Config());
    sc->set_mode(Mode(server ? Mode::SERVER : Mode::CLIENT));
    sc->set_frame(frame);
    sc->set_rng(StrongRandomAPI::Ptr(new fuzz::FixedRand()));
    sc->load_ca(fuzzkeys::ca_crt, true);
    if (server)
    {
        sc->load_cert(fuzzkeys::server_crt);
        sc->load_private_key(fuzzkeys::server_key);
        sc->load_dh(fuzzkeys::dh_pem);
    }
    else
    {
        sc->load_cert(fuzzkeys::client_crt);
        sc->load_private_key(fuzzkeys::client_key);
    }
    sc->set_tls_version_min(TLSVersion::Type::V1_2);
    f = sc->new_factory();
    return f;
}

ProtoContext::ProtoConfig::Ptr make_config(bool server, unsigned mode, Time &now, Frame::Ptr frame, StrongRandomAPI::Ptr rng, SessionStats::Ptr stats)
{
    ProtoContext::ProtoConfig::Ptr p(new ProtoContext::ProtoConfig);
    p->ssl_factory = ssl_factory(server, frame);
    if (!server)
        CryptoAlgs::allow_default_dc_algs<SSLLib::CryptoAPI>(p->ssl_factory->libctx(), false, false);
    p->dc.set_factory(new CryptoDCSelect<SSLLib::CryptoAPI>(p->ssl_factory->libctx(), frame, stats, rng));
    p->tlsprf_factory.reset(new CryptoTLSPRFFactory<SSLLib::CryptoAPI>());
    p->frame = frame;
    p->now = &now;
    p->rng = rng;
    p->prng = rng;
    p->protocol = Protocol(Protocol::UDPv4);
    p->layer = Layer(Layer::OSI_LAYER_3);
    p->comp_ctx = CompressContext(CompressContext::LZ4v2, false);
    p->dc.set_cipher(CryptoAlgs::lookup("AES-256-GCM"));
    p->dc.set_digest(CryptoAlgs::lookup("SHA256"));
    p->handshake_window = Time::Duration::seconds(60);
    p->become_primary = p->handshake_window;
    p->tls_timeout = Time::Duration::milliseconds(2000);
    p->renegotiate = Time::Duration::seconds(900);
    p->expire = p->renegotiate + p->renegotiate;
    p->keepalive_ping = Time::Duration::seconds(5);
    p->keepalive_timeout = Time::Duration::seconds(60);
    p->keepalive_timeout_early = Time::Duration::seconds(10);

    switch (mode)
    {
    case 1: // tls-auth
        p->tls_auth_factory.reset(new CryptoOvpnHMACFactory<SSLLib::CryptoAPI>());
        p->tls_auth_key.parse(fuzzkeys::tls_auth_key);
        p->set_tls_auth_digest(CryptoAlgs::lookup("SHA256"));
        p->key_direction = server ? 1 : 0;
        break;
    case 2: // tls-crypt
        p->tls_crypt_factory.reset(new CryptoTLSCryptFactory<SSLLib::CryptoAPI>());
        p->tls_crypt_key.parse(fuzzkeys::tls_auth_key);
        p->set_tls_crypt_algs();
        p->tls_crypt_ = ProtoContext::ProtoConfig::TLSCrypt::V1;
        break;
    case 3: // tls-crypt-v2
        p->tls_crypt_factory.reset(new CryptoTLSCryptFactory<SSLLib::CryptoAPI>());
        p->set_tls_crypt_algs();
        if (server)
        {
            TLSCryptV2ServerKey k;
            k.parse(fuzzkeys::tls_crypt_v2_server_key);
            k.extract_key(p->tls_crypt_key);
            p->tls_crypt_metadata_factory.reset(new CryptoTLSCryptMetadataFactory());
        }
        else
        {
            TLSCryptV2ClientKey k(p->tls_crypt_context);
            k.parse(fuzzkeys::tls_crypt_v2_client_key);
            k.extract_key(p->tls_crypt_key);
            k.extract_wkc(p->wkc);
        }
        p->tls_crypt_ = ProtoContext::ProtoConfig::TLSCrypt::V2;
        break;
    default:
        break;
    }
    return p;
}

} // namespace fuzz
